<template>
  <v-card
      class="mx-auto cursor-pointer text-center pt-4"
      max-width="450"
  >
    <div class="font-bold big text-start pb-5 pl-3">
      Total:&nbsp; <span class="price">{{ amount }}</span>
    </div>
    <v-carousel
        cycle
        hide-delimiter-background
        :show-arrows="false"
        height="240">
      <v-carousel-item
          v-for="image in images"
          :src="image.image"
          cover
          loading="lazy"
      >
      </v-carousel-item>
    </v-carousel>
    <v-card-text>
      Customer will be redirected on brand checkout page
    </v-card-text>
    <v-card-actions class="justify-center pb-5">
      <v-btn
          text="Pay"
          variant="flat"
          :color="colors.primary"
          @click="redirect"
      >
      </v-btn>
    </v-card-actions>
  </v-card>
</template>

<script>
import $checkout from 'flitt-js-sdk';

import colors from "@/utils/colors.js";
import params from "@/utils/params";


export default {
  name: "RedirectWidget",
  props: {
    amount: 0,
    images: {
      type: Array,
      default: () => []
    },
  },
  methods: {
    redirect() {
      const cardData = {
        amount: this.amount * 100,
        merchant_id: params.params.merchant_id,
        currency: params.params.currency,
        lang: params.params.lang,
      };
      $checkout('Api').scope(function () {
        this.request('api.checkout.token', 'get', cardData).done(function (model) {
          window.location.href = model.data.checkout_url;
        }).fail(function (model) {
          console.debug(model)
        });
      });
    },
  },
  data() {
    return {
      colors: colors
    };
  },
};
</script>